/* The Grounded Readings Library, group abr (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["abr"] = [{"id":"abr-psalm-1","title":"Psalm 1","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["daily","morning"],"text":"Happy is the man that hath not walked in the counsel of the wicked, Nor stood in the way of sinners, nor sat in the seat of the scornful.\nBut his delight is in the law of the LORD; and in His law doth he meditate day and night.\nAnd he shall be like a tree planted by streams of water, that bringeth forth its fruit in its season, and whose leaf doth not wither; and in whatsoever he doeth he shall prosper.\nNot so the wicked; but they are like the chaff which the wind driveth away.\nTherefore the wicked shall not stand in the judgment, nor sinners in the congregation of the righteous.\nFor the LORD regardeth the way of the righteous; but the way of the wicked shall perish.","note":"The opening psalm, read for steady living and at the start of a day of study.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 1:1-6","url":"https://www.sefaria.org/Psalms.1.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-4","title":"From Psalm 4","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["evening","peace"],"text":"Answer me when I call, O God of my righteousness, Thou who didst set me free when I was in distress; be gracious unto me, and hear my prayer.\nTremble, and sin not; commune with your own heart upon your bed, and be still. Selah\nMany there are that say: 'Oh that we could see some good!' LORD, lift Thou up the light of Thy countenance upon us.\nIn peace will I both lay me down and sleep; for Thou, LORD, makest me dwell alone in safety.","note":"An evening psalm; its last line is said by many before sleep.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 4:2-9","url":"https://www.sefaria.org/Psalms.4.2-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-8","title":"Psalm 8","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","birth","gratitude"],"text":"O LORD, our Lord, How glorious is Thy name in all the earth! Whose majesty is rehearsed above the heavens.\nOut of the mouth of babes and sucklings hast Thou founded strength, Because of Thine adversaries; That Thou mightest still the enemy and the avenger.\nWhen I behold Thy heavens, the work of Thy fingers, The moon and the stars, which Thou hast established;\nWhat is man, that Thou art mindful of him? And the son of man, that Thou thinkest of him?\nYet Thou hast made him but little lower than the angels, And hast crowned him with glory and honour.\nThou hast made him to have dominion over the works of Thy hands; Thou hast put all things under His feet:\nSheep and oxen, all of them, Yea, and the beasts of the field;\nThe fowl of the air, and the fish of the sea; Whatsoever passeth through the paths of the seas.\nO LORD, our Lord, How glorious is Thy name in all the earth!","note":"Read under the night sky, at a birth, or when wonder needs words.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 8:2-10","url":"https://www.sefaria.org/Psalms.8.2-10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-15","title":"Psalm 15","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","daily"],"text":"LORD, who shall sojourn in Thy tabernacle? Who shall dwell upon Thy holy mountain?\nHe that walketh uprightly, and worketh righteousness, And speaketh truth in his heart;\nThat hath no slander upon his tongue, Nor doeth evil to his fellow, Nor taketh up a reproach against his neighbour;\nIn whose eyes a vile person is despised, But he honoureth them that fear the LORD; He that sweareth to his own hurt, and changeth not;\nHe that putteth not out his money on interest, Nor taketh a bribe against the innocent. He that doeth these things shall never be moved.","note":"Often read at a Jewish funeral to describe a life of integrity.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 15:1-5","url":"https://www.sefaria.org/Psalms.15.1-5?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-16","title":"From Psalm 16","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","hope","comfort"],"text":"I have set the LORD always before me; Surely He is at my right hand, I shall not be moved.\nTherefore my heart is glad, and my glory rejoiceth; my flesh also dwelleth in safety;\nFor Thou wilt not abandon my soul to the nether-world; Neither wilt Thou suffer Thy godly one to see the pit.\nThou makest me to know the path of life; In Thy presence is fulness of joy, In Thy right hand bliss for evermore.","note":"Read at funerals and in the house of mourning for its path of life.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 16:8-11","url":"https://www.sefaria.org/Psalms.16.8-11?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-19","title":"From Psalm 19","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","morning"],"text":"The heavens declare the glory of God, and the firmament showeth His handiwork;\nDay unto day uttereth speech, and night unto night revealeth knowledge;\nThere is no speech, there are no words, neither is their voice heard.\nTheir line is gone out through all the earth, and their words to the end of the world. In them hath He set a tent for the sun,\nWhich is as a bridegroom coming out of his chamber, and rejoiceth as a strong man to run his course.\nHis going forth is from the end of the heaven, and his circuit unto the ends of it; and there is nothing hid from the heat thereof.","note":"A Sabbath morning psalm of the heavens and the sun.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 19:2-7","url":"https://www.sefaria.org/Psalms.19.2-7?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-23","title":"Psalm 23","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","dying","comfort","grief"],"text":"The LORD is my shepherd; I shall not want.\nHe maketh me to lie down in green pastures; He leadeth me beside the still waters.\nHe restoreth my soul; He guideth me in straight paths for His name's sake.\nYea, though I walk through the valley of the shadow of death, I will fear no evil, for Thou art with me; Thy rod and Thy staff, they comfort me.\nThou preparest a table before me in the presence of mine enemies; Thou hast anointed my head with oil; my cup runneth over.\nSurely goodness and mercy shall follow me all the days of my life; And I shall dwell in the house of the LORD for ever.","translit":"Mizmor l'David. Adonai ro'i, lo echsar.","note":"The best loved psalm of comfort, said at the bedside, the funeral, and the graveside.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 23:1-6","url":"https://www.sefaria.org/Psalms.23.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-24","title":"Psalm 24","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["blessing","home"],"text":"The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein.\nFor He hath founded it upon the seas, and established it upon the floods.\nWho shall ascend into the mountain of the LORD? And who shall stand in His holy place?\nHe that hath clean hands, and a pure heart; Who hath not taken My name in vain, and hath not sworn deceitfully.\nHe shall receive a blessing from the LORD, and righteousness from the God of his salvation.\nSuch is the generation of them that seek after Him, that seek Thy face, even Jacob. Selah\nLift up your heads, O ye gates, and be ye lifted up, ye everlasting doors; that the King of glory may come in.\n'Who is the King of glory?' 'The LORD strong and mighty, The LORD mighty in battle.'\nLift up your heads, O ye gates, Yea, lift them up, ye everlasting doors; That the King of glory may come in.\n'Who then is the King of glory?' 'The LORD of hosts; He is the King of glory.' Selah","note":"Sung on Sunday mornings in the synagogue and when the Torah returns to the ark.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 24:1-10","url":"https://www.sefaria.org/Psalms.24.1-10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-27","title":"Psalm 27","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","hope","season"],"text":"The LORD is my light and my salvation; whom shall I fear? The LORD is the stronghold of my life; of whom shall I be afraid?\nWhen evil-doers came upon me to eat up my flesh, Even mine adversaries and my foes, they stumbled and fell.\nThough a host should encamp against me, My heart shall not fear; Though war should rise up against me, Even then will I be confident.\nOne thing have I asked of the LORD, that will I seek after: That I may dwell in the house of the LORD all the days of my life, To behold the graciousness of the LORD, and to visit early in His temple.\nFor He concealeth me in His pavilion in the day of evil; He hideth me in the covert of His tent; He lifteth me up upon a rock.\nAnd now shall my head be lifted up above mine enemies round about me; And I will offer in His tabernacle sacrifices with trumpet-sound; I will sing, yea, I will sing praises unto the LORD.\nHear, O LORD, when I call with my voice, And be gracious unto me, and answer me.\nIn Thy behalf my heart hath said: 'Seek ye My face'; Thy face, LORD, will I seek.\nHide not Thy face far from me; Put not Thy servant away in anger; Thou hast been my help; Cast me not off, neither forsake me, O God of my salvation.\nFor though my father and my mother have forsaken me, The LORD will take me up.\nTeach me Thy way, O LORD; And lead me in an even path, Because of them that lie in wait for me.\nDeliver me not over unto the will of mine adversaries; For false witnesses are risen up against me, and such as breathe out violence.\nIf I had not believed to look upon the goodness of the LORD In the land of the living!\nWait on the LORD; Be strong, and let thy heart take courage; Yea, wait thou for the LORD.","note":"Said daily through the season of repentance before the High Holy Days.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 27:1-14","url":"https://www.sefaria.org/Psalms.27.1-14?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-30","title":"From Psalm 30","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["healing","gratitude","hope"],"text":"I will extol thee, O LORD, for Thou hast raised me up, and hast not suffered mine enemies to rejoice over me.\nO LORD my God, I cried unto Thee, and Thou didst heal me;\nO LORD, Thou broughtest up my soul from the nether-world; Thou didst keep me alive, that I should not go down to the pit.\nSing praise unto the LORD, O ye His godly ones, and give thanks to His holy name.\nFor His anger is but for a moment, His favour is for a life-time; weeping may tarry for the night, but joy cometh in the morning.\nNow I had said in my security: 'I shall never be moved.'\nThou hadst established, O LORD, in Thy favour my mountain as a stronghold, Thou didst hide Thy face; I was affrighted.\nUnto Thee, O LORD, did I call, And unto the LORD I made supplication:\n'What profit is there in my blood, when I go down to the pit? Shall the dust praise Thee? shall it declare Thy truth?\nHear, O LORD, and be gracious unto me; LORD, be Thou my helper.'\nThou didst turn for me my mourning into dancing; Thou didst loose my sackcloth, and gird me with gladness;\nSo that my glory may sing praise to Thee, and not be silent; O LORD my God, I will give thanks unto Thee for ever.","note":"A psalm of thanks after illness: weeping may tarry for the night, but joy cometh in the morning.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 30:2-13","url":"https://www.sefaria.org/Psalms.30.2-13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-31","title":"From Psalm 31","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["dying","evening","comfort"],"text":"In Thee, O LORD, have I taken refuge; let me never be ashamed; Deliver me in Thy righteousness.\nIncline Thine ear unto me, deliver me speedily; Be Thou to me a rock of refuge, even a fortress of defence, to save me.\nFor Thou art my rock and my fortress; Therefore for Thy name's sake lead me and guide me.\nBring me forth out of the net that they have hidden for me; For Thou art my stronghold.\nInto Thy hand I commit my spirit; Thou hast redeemed me, O LORD, Thou God of truth.","note":"Its line \"Into Thy hand I commit my spirit\" is said at the bedside and before sleep.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 31:2-6","url":"https://www.sefaria.org/Psalms.31.2-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-34","title":"From Psalm 34","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["gratitude","daily"],"text":"I will bless the LORD at all times; His praise shall continually be in my mouth.\nMy soul shall glory in the LORD; The humble shall hear thereof, and be glad.\nO magnify the LORD with me, And let us exalt His name together.\nI sought the LORD, and He answered me, And delivered me from all my fears.\nThey looked unto Him, and were radiant; And their faces shall never be abashed.\nThis poor man cried, and the LORD heard, And saved him out of all his troubles.\nThe angel of the LORD encampeth round about them that fear Him, And delivereth them.\nO consider and see that the LORD is good; Happy is the man that taketh refuge in Him.\nO fear the LORD, ye His holy ones; For there is no want to them that fear Him.\nThe young lions do lack, and suffer hunger; But they that seek the LORD want not any good thing.","note":"A psalm of thanks sung on Sabbath mornings.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 34:2-11","url":"https://www.sefaria.org/Psalms.34.2-11?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-36","title":"From Psalm 36","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","hope"],"text":"Thy lovingkindness, O LORD, is in the heavens; Thy faithfulness reacheth unto the skies.\nThy righteousness is like the mighty mountains; Thy judgments are like the great deep; Man and beast Thou preservest, O LORD.\nHow precious is Thy lovingkindness, O God! And the children of men take refuge in the shadow of Thy wings.\nThey are abundantly satisfied with the fatness of Thy house; And Thou makest them drink of the river of Thy pleasures.\nFor with Thee is the fountain of life; In Thy light do we see light.","note":"Its last line, \"In Thy light do we see light,\" is loved across many traditions.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 36:6-10","url":"https://www.sefaria.org/Psalms.36.6-10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-42","title":"From Psalm 42","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["grief","comfort"],"text":"As the hart panteth after the water brooks, so panteth my soul after Thee, O God.\nMy soul thirsteth for God, for the living God: 'When shall I come and appear before God?'\nMy tears have been my food day and night, while they say unto me all the day: 'Where is Thy God?'\nThese things I remember, and pour out my soul within me, how I passed on with the throng, and led them to the house of God, with the voice of joy and praise, a multitude keeping holyday.\nWhy art thou cast down, O my soul? And why moanest thou within me? Hope thou in God; for I shall yet praise Him for the salvation of His countenance.","note":"For a thirsty, sorrowing soul that is still reaching toward hope.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 42:2-6","url":"https://www.sefaria.org/Psalms.42.2-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-46","title":"Psalm 46","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","peace"],"text":"God is our refuge and strength, A very present help in trouble.\nTherefore will we not fear, though the earth do change, And though the mountains be moved into the heart of the seas;\nThough the waters thereof roar and foam, Though the mountains shake at the swelling thereof. Selah\nThere is a river, the streams whereof make glad the city of God, The holiest dwelling-place of the Most High.\nGod is in the midst of her, she shall not be moved; God shall help her, at the approach of morning.\nNations were in tumult, kingdoms were moved; He uttered His voice, the earth melted.\nThe LORD of hosts is with us; The God of Jacob is our high tower. Selah\nCome, behold the works of the LORD, Who hath made desolations in the earth.\nHe maketh wars to cease unto the end of the earth; He breaketh the bow, and cutteth the spear in sunder; He burneth the chariots in the fire.\n'Let be, and know that I am God; I will be exalted among the nations, I will be exalted in the earth.'\nThe LORD of hosts is with us; The God of Jacob is our high tower. Selah","note":"For times of upheaval; ends with the call to be still and know.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 46:2-12","url":"https://www.sefaria.org/Psalms.46.2-12?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-51","title":"From Psalm 51","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["forgiveness","morning"],"text":"Create me a clean heart, O God; and renew a stedfast spirit within me.\nCast me not away from Thy presence; and take not Thy holy spirit from me.\nRestore unto me the joy of Thy salvation; and let a willing spirit uphold me.","note":"A prayer for a clean heart and a willing spirit.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 51:12-14","url":"https://www.sefaria.org/Psalms.51.12-14?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-61","title":"From Psalm 61","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","healing"],"text":"Hear my cry, O God; Attend unto my prayer.\nFrom the end of the earth will I call unto Thee, when my heart fainteth; Lead me to a rock that is too high for me.\nFor Thou hast been a refuge for me, A tower of strength in the face of the enemy.\nI will dwell in Thy Tent for ever; I will take refuge in the covert of Thy wings. Selah","note":"For a fainting heart that needs a rock higher than itself.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 61:2-5","url":"https://www.sefaria.org/Psalms.61.2-5?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-62","title":"From Psalm 62","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["peace","daily"],"text":"Only for God doth my soul wait in stillness; From Him cometh my salvation.\nHe only is my rock and my salvation, My high tower, I shall not be greatly moved.","note":"A short psalm of waiting in stillness.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 62:2-3","url":"https://www.sefaria.org/Psalms.62.2-3?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-63","title":"From Psalm 63","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["morning","comfort"],"text":"O God, Thou art my God, earnestly will I seek Thee; My soul thirsteth for Thee, my flesh longeth for Thee, In a dry and weary land, where no water is.\nSo have I looked for Thee in the sanctuary, To see Thy power and Thy glory.\nFor Thy lovingkindness is better than life; My lips shall praise Thee.\nSo will I bless Thee as long as I live; In Thy name will I lift up my hands.\nMy soul is satisfied as with marrow and fatness; And my mouth doth praise Thee with joyful lips;\nWhen I remember Thee upon my couch, And meditate on Thee in the night-watches.\nFor Thou hast been my help, And in the shadow of Thy wings do I rejoice.\nMy soul cleaveth unto Thee; Thy right hand holdeth me fast.","note":"A psalm of longing and of rest in the shadow of wings.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 63:2-9","url":"https://www.sefaria.org/Psalms.63.2-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-65","title":"From Psalm 65","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","gratitude","season"],"text":"Thou hast remembered the earth, and watered her, greatly enriching her, with the river of God that is full of water; Thou preparest them corn, for so preparest Thou her.\nWatering her ridges abundantly, settling down the furrows thereof, Thou makest her soft with showers; Thou blessest the growth thereof.\nThou crownest the year with Thy goodness; and Thy paths drop fatness.\nThe pastures of the wilderness do drop; and the hills are girded with joy.\nThe meadows are clothed with flocks; the valleys also are covered over with corn; they shout for joy, yea, they sing.","note":"A harvest psalm for thanksgiving and the turning of the year.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 65:10-14","url":"https://www.sefaria.org/Psalms.65.10-14?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-84","title":"From Psalm 84","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["home","hope"],"text":"How lovely are Thy tabernacles, O LORD of hosts!\nMy soul yearneth, yea, even pineth for the courts of the LORD; my heart and my flesh sing for joy unto the living God.\nYea, the sparrow hath found a house, and the swallow a nest for herself, Where she may lay her young; Thine altars, O LORD of hosts, My King, and my God\nHappy are they that dwell in Thy house, they are ever praising Thee. Selah\nHappy is the man whose strength is in Thee; in whose heart are the highways.\nPassing through the valley of Baca they make it a place of springs; yea, the early rain clotheth it with blessings.\nThey go from strength to strength, every one of them appeareth before God in Zion.\nO LORD God of hosts, hear my prayer; give ear, O God of Jacob. Selah\nBehold, O God our shield, and look upon the face of Thine anointed.\nFor a day in Thy courts is better than a thousand; I had rather stand at the threshold of the house of my God, than to dwell in the tents of wickedness.\nFor the LORD God is a sun and a shield; the LORD giveth grace and glory; No good thing will He withhold from them that walk uprightly.\nO LORD of hosts, happy is the man that trusteth in Thee.","note":"They go from strength to strength: read for a journey, a new home, or a life well walked.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 84:2-13","url":"https://www.sefaria.org/Psalms.84.2-13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-90","title":"Psalm 90","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","grief"],"text":"Lord, Thou hast been our dwelling-place in all generations.\nBefore the mountains were brought forth, Or ever Thou hadst formed the earth and the world, Even from everlasting to everlasting, Thou art God.\nThou turnest man to contrition; And sayest: 'Return, ye children of men.'\nFor a thousand years in Thy sight Are but as yesterday when it is past, And as a watch in the night.\nThou carriest them away as with a flood; they are as a sleep; In the morning they are like grass which groweth up.\nIn the morning it flourisheth, and groweth up; In the evening it is cut down, and withereth.\nFor we are consumed in Thine anger, And by Thy wrath are we hurried away.\nThou hast set our iniquities before Thee, Our secret sins in the light of Thy countenance.\nFor all our days are passed away in Thy wrath; We bring our years to an end as a tale that is told.\nThe days of our years are threescore years and ten, Or even by reason of strength fourscore years; Yet is their pride but travail and vanity; For it is speedily gone, and we fly away.\nWho knoweth the power of Thine anger, And Thy wrath according to the fear that is due unto Thee?\nSo teach us to number our days, That we may get us a heart of wisdom.\nReturn, O LORD; how long? And let it repent Thee concerning Thy servants.\nO satisfy us in the morning with Thy mercy; That we may rejoice and be glad all our days.\nMake us glad according to the days wherein Thou hast afflicted us, According to the years wherein we have seen evil.\nLet Thy work appear unto Thy servants, And Thy glory upon their children.\nAnd let the graciousness of the Lord our God be upon us; Establish Thou also upon us the work of our hands; Yea, the work of our hands establish Thou it.","note":"A prayer of Moses on the shortness of life and the work of our hands; read at funerals.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 90:1-17","url":"https://www.sefaria.org/Psalms.90.1-17?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-91","title":"Psalm 91","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","comfort","evening"],"text":"O thou that dwellest in the covert of the Most High, And abidest in the shadow of the Almighty;\nI will say of the LORD, who is my refuge and my fortress, My God, in whom I trust,\nThat He will deliver thee from the snare of the fowler, And from the noisome pestilence.\nHe will cover thee with His pinions, And under His wings shalt thou take refuge; His truth is a shield and a buckler.\nThou shalt not be afraid of the terror by night, Nor of the arrow that flieth by day;\nOf the pestilence that walketh in darkness, Nor of the destruction that wasteth at noonday.\nA thousand may fall at Thy side, And ten thousand at Thy right hand; It shall not come nigh thee.\nOnly with thine eyes shalt thou behold, And see the recompense of the wicked.\nFor thou hast made the LORD who is my refuge, Even the Most High, thy habitation.\nThere shall no evil befall thee, Neither shall any plague come nigh thy tent.\nFor He will give His angels charge over thee, To keep thee in all thy ways.\nThey shall bear thee upon their hands, Lest thou dash thy foot against a stone.\nThou shalt tread upon the lion and asp; The young lion and the serpent shalt thou trample under feet.\n'Because he hath set his love upon Me, therefore will I deliver him; I will set him on high, because he hath known My name.\nHe shall call upon Me, and I will answer him; I will be with him in trouble; I will rescue him, and bring him to honour.\nWith long life will I satisfy him, And make Him to behold My salvation.'","note":"A psalm of shelter, said at the graveside and before sleep.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 91:1-16","url":"https://www.sefaria.org/Psalms.91.1-16?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-92","title":"From Psalm 92","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["season","gratitude","daily"],"text":"It is a good thing to give thanks unto the LORD, And to sing praises unto Thy name, O Most High;\nTo declare Thy lovingkindness in the morning, And Thy faithfulness in the night seasons,\nWith an instrument of ten strings, and with the psaltery; With a solemn sound upon the harp.\nFor Thou, LORD, hast made me glad through Thy work; I will exult in the works of Thy hands.\nHow great are Thy works, O LORD! Thy thoughts are very deep.\nA brutish man knoweth not, Neither doth a fool understand this.\nWhen the wicked spring up as the grass, And when all the workers of iniquity do flourish; It is that they may be destroyed for ever.\nBut Thou, O LORD, art on high for evermore.\nFor, lo, Thine enemies, O LORD, For, lo, Thine enemies shall perish: All the workers of iniquity shall be scattered.\nBut my horn hast Thou exalted like the horn of the wild-ox; I am anointed with rich oil.\nMine eye also hath gazed on them that lie in wait for me, Mine ears have heard my desire of the evil-doers that rise up against me.\nThe righteous shall flourish like the palm-tree; He shall grow like a cedar in Lebanon.\nPlanted in the house of the LORD, They shall flourish in the courts of our God.\nThey shall still bring forth fruit in old age; They shall be full of sap and richness;\nTo declare that the LORD is upright, My Rock, in whom there is no unrighteousness.","note":"The Sabbath psalm: the righteous shall flourish like the palm tree.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 92:2-16","url":"https://www.sefaria.org/Psalms.92.2-16?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-96","title":"Psalm 96","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","nature"],"text":"O sing unto the LORD a new song; Sing unto the LORD, all the earth.\nSing unto the LORD, bless His name; Proclaim His salvation from day to day.\nDeclare His glory among the nations, His marvellous works among all the peoples.\nFor great is the LORD, and highly to be praised; He is to be feared above all gods.\nFor all the gods of the peoples are things of nought; But the LORD made the heavens.\nHonour and majesty are before Him; Strength and beauty are in His sanctuary.\nAscribe unto the LORD, ye kindreds of the peoples, Ascribe unto the LORD glory and strength.\nAscribe unto the LORD the glory due unto His name; Bring an offering, and come into His courts.\nO worship the LORD in the beauty of holiness; Tremble before Him, all the earth.\nSay among the nations: 'The LORD reigneth.' The world also is established that it cannot be moved; He will judge the peoples with equity.\nLet the heavens be glad, and let the earth rejoice; Let the sea roar, and the fulness thereof;\nLet the field exult; and all that is therein; Then shall all the trees of the wood sing for joy;\nBefore the LORD, for He is come; For He is come to judge the earth; He will judge the world with righteousness, And the peoples in His faithfulness.","note":"Sung at the welcoming of the Sabbath: let the trees of the wood sing for joy.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 96:1-13","url":"https://www.sefaria.org/Psalms.96.1-13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-100","title":"Psalm 100","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["gratitude","celebration"],"text":"Shout unto the LORD, all the earth.\nServe the LORD with gladness; come before His presence with singing.\nKnow ye that the LORD He is God; it is He that hath made us, and we are His, His people, and the flock of His pasture.\nEnter into His gates with thanksgiving, and into His courts with praise; give thanks unto Him, and bless His name.\nFor the LORD is good; His mercy endureth for ever; and His faithfulness unto all generations.","note":"The psalm of thanksgiving, said on weekday mornings.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 100:1-5","url":"https://www.sefaria.org/Psalms.100.1-5?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-103","title":"Psalm 103","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","gratitude","forgiveness"],"text":"Bless the LORD, O my soul; And all that is within me, bless His holy name.\nBless the LORD, O my soul, And forget not all His benefits;\nWho forgiveth all thine iniquity; Who healeth all Thy diseases;\nWho redeemeth Thy life from the pit; Who encompasseth thee with lovingkindness and tender mercies;\nWho satisfieth thine old age with good things; So that Thy youth is renewed like the eagle.\nThe LORD executeth righteousness, And acts of justice for all that are oppressed.\nHe made known His ways unto Moses, His doings unto the children of Israel.\nThe LORD is full of compassion and gracious, Slow to anger, and plenteous in mercy.\nHe will not always contend; Neither will He keep His anger for ever.\nHe hath not dealt with us after our sins, Nor requited us according to our iniquities.\nFor as the heaven is high above the earth, So great is His mercy toward them that fear Him.\nAs far as the east is from the west, So far hath He removed our transgressions from us.\nLike as a father hath compassion upon his children, So hath the LORD compassion upon them that fear Him.\nFor He knoweth our frame; He remembereth that we are dust.\nAs for man, his days are as grass; As a flower of the field, so he flourisheth.\nFor the wind passeth over it, and it is gone; And the place thereof knoweth it no more.\nBut the mercy of the LORD is from everlasting to everlasting upon them that fear Him, And His righteousness unto children's children;\nTo such as keep His covenant, And to those that remember His precepts to do them.\nThe LORD hath established His throne in the heavens; And His kingdom ruleth over all.\nBless the LORD, ye angels of His, Ye mighty in strength, that fulfil His word, Hearkening unto the voice of His word.\nBless the LORD, all ye His hosts; Ye ministers of His, that do His pleasure.\nBless the LORD, all ye His works, In all places of His dominion; Bless the LORD, O my soul.","note":"Bless the LORD, O my soul: read at funerals for its picture of mercy and of our days like grass.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 103:1-22","url":"https://www.sefaria.org/Psalms.103.1-22?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-104","title":"From Psalm 104","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","gratitude"],"text":"How manifold are Thy works, O LORD! In wisdom hast Thou made them all; The earth is full of Thy creatures.\nThou sendest forth Thy spirit, they are created; and Thou renewest the face of the earth.\nMay the glory of the LORD endure for ever; let the LORD rejoice in His works!\nI will sing unto the LORD as long as I live; I will sing praise to my God while I have any being.\nLet my musing be sweet unto Him; as for me, I will rejoice in the LORD.","note":"The great creation psalm, read at the New Moon and in nature.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 104:24-34","url":"https://www.sefaria.org/Psalms.104.24-34?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-113","title":"Psalm 113","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","birth"],"text":"Hallelujah. Praise, O ye servants of the LORD, Praise the name of the LORD.\nBlessed be the name of the LORD From this time forth and for ever.\nFrom the rising of the sun unto the going down thereof The LORD'S name is to be praised.\nThe LORD is high above all nations, His glory is above the heavens.\nWho is like unto the LORD our God, That is enthroned on high,\nThat looketh down low Upon heaven and upon the earth?\nWho raiseth up the poor out of the dust, And lifteth up the needy out of the dunghill;\nThat He may set him with princes, Even with the princes of His people.\nWho maketh the barren woman to dwell in her house As a joyful mother of children. Hallelujah.","note":"The first psalm of Hallel, sung on festivals.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 113:1-9","url":"https://www.sefaria.org/Psalms.113.1-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-116","title":"From Psalm 116","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["healing","gratitude"],"text":"I love that the LORD should hear my voice and my supplications.\nBecause He hath inclined His ear unto me, Therefore will I call upon Him all my days.\nThe cords of death compassed me, And the straits of the nether-world got hold upon me; I found trouble and sorrow.\nBut I called upon the name of the LORD: 'I beseech thee, O LORD, deliver my soul.'\nGracious is the LORD, and righteous; Yea, our God is compassionate.\nThe LORD preserveth the simple; I was brought low, and He saved me.\nReturn, O my soul, unto Thy rest; For the LORD hath dealt bountifully with thee.\nFor thou hast delivered my soul from death, Mine eyes from tears, And my feet from stumbling.\nI shall walk before the LORD In the lands of the living.","note":"A psalm of thanks after being brought through danger.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 116:1-9","url":"https://www.sefaria.org/Psalms.116.1-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-118","title":"This Is the Day","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","wedding","morning"],"text":"This is the day which the LORD hath made; We will rejoice and be glad in it.","note":"One line from the Hallel psalms for a day of joy.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 118:24","url":"https://www.sefaria.org/Psalms.118.24?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-121","title":"Psalm 121","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","comfort","dying","blessing"],"text":"I will lift up mine eyes unto the mountains: From whence shall my help come?\nMy help cometh from the LORD, Who made heaven and earth.\nHe will not suffer thy foot to be moved; He that keepeth thee will not slumber.\nBehold, He that keepeth Israel Doth neither slumber nor sleep.\nThe LORD is thy keeper; The LORD is thy shade upon thy right hand.\nThe sun shall not smite thee by day, Nor the moon by night.\nThe LORD shall keep thee from all evil; He shall keep thy soul.\nThe LORD shall guard thy going out and thy coming in, From this time forth and for ever.","translit":"Shir lama'alot. Esa einai el heharim, me'ayin yavo ezri.","note":"A psalm for the journey, said at the bedside, the funeral, and before travel.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 121:1-8","url":"https://www.sefaria.org/Psalms.121.1-8?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-122","title":"Psalm 122","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["peace","celebration"],"text":"I rejoiced when they said unto me: 'Let us go unto the house of the LORD.'\nOur feet are standing within thy gates, O Jerusalem;\nJerusalem, that art builded as a city that is compact together;\nWhither the tribes went up, even the tribes of the LORD, as a testimony unto Israel, to give thanks unto the name of the LORD.\nFor there were set thrones for judgment, the thrones of the house of David.\nPray for the peace of Jerusalem; May they prosper that love thee.\nPeace be within thy walls, and prosperity within thy palaces.\nFor my brethren and companions' sakes, I will now say: 'Peace be within thee.'\nFor the sake of the house of the LORD our God I will seek thy good.","note":"A pilgrim song of joy and of prayer for peace.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 122:1-9","url":"https://www.sefaria.org/Psalms.122.1-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-126","title":"Psalm 126","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","gratitude"],"text":"When the LORD brought back those that returned to Zion, We were like unto them that dream.\nThen was our mouth filled with laughter, and our tongue with singing; then said they among the nations: 'The LORD hath done great things with these.'\nThe LORD hath done great things with us; we are rejoiced.\nTurn our captivity, O LORD, as the streams in the dry land.\nThey that sow in tears Shall reap in joy.\nThough he goeth on his way weeping that beareth the measure of seed, He shall come home with joy, bearing his sheaves.","note":"Sung before grace after Sabbath meals: they that sow in tears shall reap in joy.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 126:1-6","url":"https://www.sefaria.org/Psalms.126.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-127","title":"Psalm 127","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["home","birth"],"text":"Except the LORD build the house, They labour in vain that build it; Except the LORD keep the city, The watchman waketh but in vain.\nIt is vain for you that ye rise early, and sit up late, Ye that eat the bread of toil; So He giveth unto His beloved in sleep.\nLo, children are a heritage of the LORD; The fruit of the womb is a reward.\nAs arrows in the hand of a mighty man, So are the children of one's youth.\nHappy is the man that hath his quiver full of them; They shall not be put to shame, When they speak with their enemies in the gate.","note":"For the building of a house and a family.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 127:1-5","url":"https://www.sefaria.org/Psalms.127.1-5?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-128","title":"Psalm 128","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["wedding","home"],"text":"Happy is every one that feareth the LORD, That walketh in His ways.\nWhen thou eatest the labour of thy hands, Happy shalt thou be, and it shall be well with thee.\nThy wife shall be as a fruitful vine, in the innermost parts of thy house; Thy children like olive plants, round about thy table.\nBehold, surely thus shall the man be blessed That feareth the LORD.\nThe LORD bless thee out of Zion; And see thou the good of Jerusalem all the days of thy life;\nAnd see thy children's children. Peace be upon Israel!","note":"Read at weddings and for a blessed home: thy children like olive plants round about thy table.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 128:1-6","url":"https://www.sefaria.org/Psalms.128.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-130","title":"Psalm 130","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["grief","hope","funeral"],"text":"Out of the depths have I called Thee, O LORD.\nLord, hearken unto my voice; let Thine ears be attentive to the voice of my supplications.\nIf Thou, LORD, shouldest mark iniquities, O Lord, who could stand?\nFor with Thee there is forgiveness, that Thou mayest be feared.\nI wait for the LORD, my soul doth wait, and in His word do I hope.\nMy soul waiteth for the Lord, more than watchmen for the morning; yea, more than watchmen for the morning.\nO Israel, hope in the LORD; for with the LORD there is mercy, and with Him is plenteous redemption.\nAnd He will redeem Israel from all his iniquities.","note":"Out of the depths: said in the house of mourning and in seasons of waiting.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 130:1-8","url":"https://www.sefaria.org/Psalms.130.1-8?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-131","title":"Psalm 131","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["peace","comfort"],"text":"LORD, my heart is not haughty, nor mine eyes lofty; Neither do I exercise myself in things too great, or in things too wonderful for me.\nSurely I have stilled and quieted my soul; Like a weaned child with his mother; My soul is with me like a weaned child.\nO Israel, hope in the LORD From this time forth and for ever.","note":"A quiet psalm of a soul at rest like a weaned child.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 131:1-3","url":"https://www.sefaria.org/Psalms.131.1-3?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-133","title":"Psalm 133","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","wedding","home"],"text":"Behold, how good and how pleasant it is For brethren to dwell together in unity!\nIt is like the precious oil upon the head, Coming down upon the beard; Even Aaron's beard, That cometh down upon the collar of his garments;\nLike the dew of Hermon, That cometh down upon the mountains of Zion; For there the LORD commanded the blessing, Even life for ever.","translit":"Hineh mah tov u'mah na'im shevet achim gam yachad.","note":"Sung when family and friends gather: how good and how pleasant it is.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 133:1-3","url":"https://www.sefaria.org/Psalms.133.1-3?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-139","title":"From Psalm 139","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","dying","birth"],"text":"O LORD, Thou hast searched me, and known me.\nThou knowest my downsitting and mine uprising, Thou understandest my thought afar off.\nThou measurest my going about and my lying down, And art acquainted with all my ways.\nFor there is not a word in my tongue, But, lo, O LORD, Thou knowest it altogether.\nThou hast hemmed me in behind and before, And laid Thy hand upon me.\nSuch knowledge is too wonderful for me; Too high, I cannot attain unto it.\nWhither shall I go from Thy spirit? Or whither shall I flee from Thy presence?\nIf I ascend up into heaven, Thou art there; If I make my bed in the nether-world, behold, Thou art there.\nIf I take the wings of the morning, And dwell in the uttermost parts of the sea;\nEven there would Thy hand lead me, And Thy right hand would hold me.\nAnd if I say: 'Surely the darkness shall envelop me, And the light about me shall be night';\nEven the darkness is not too dark for Thee, But the night shineth as the day; The darkness is even as the light.","note":"For any place a person may go, even the dark: Thou art there.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 139:1-12","url":"https://www.sefaria.org/Psalms.139.1-12?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-145","title":"From Psalm 145","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["gratitude","daily"],"text":"The LORD is gracious, and full of compassion; Slow to anger, and of great mercy.\nThe LORD is good to all; And His tender mercies are over all His works.\nAll Thy works shall praise Thee, O LORD; And Thy saints shall bless Thee.\nThey shall speak of the glory of Thy kingdom, And talk of Thy might;\nTo make known to the sons of men His mighty acts, And the glory of the majesty of His kingdom.\nThy kingdom is a kingdom for all ages, And Thy dominion endureth throughout all generations.\nThe LORD upholdeth all that fall, And raiseth up all those that are bowed down.\nThe eyes of all wait for Thee, And Thou givest them their food in due season.\nThou openest Thy hand, And satisfiest every living thing with favour.\nThe LORD is righteous in all His ways, And gracious in all His works.\nThe LORD is nigh unto all them that call upon Him, To all that call upon Him in truth.\nHe will fulfil the desire of them that fear Him; He also will hear their cry, and will save them.","note":"From Ashrei, said three times a day; the LORD upholdeth all that fall.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 145:8-19","url":"https://www.sefaria.org/Psalms.145.8-19?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-146","title":"Psalm 146","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","daily"],"text":"Hallelujah. Praise the LORD, O my soul.\nI will praise the LORD while I live; I will sing praises unto my God while I have my being.\nPut not your trust in princes, Nor in the son of man, in whom there is no help.\nHis breath goeth forth, he returneth to his dust; In that very day his thoughts perish.\nHappy is he whose help is the God of Jacob, Whose hope is in the LORD his God,\nWho made heaven and earth, The sea, and all that in them is; Who keepeth truth for ever;\nWho executeth justice for the oppressed; Who giveth bread to the hungry. The LORD looseth the prisoners;\nThe LORD openeth the eyes of the blind; The LORD raiseth up them that are bowed down; The LORD loveth the righteous;\nThe LORD preserveth the strangers; He upholdeth the fatherless and the widow; But the way of the wicked He maketh crooked.\nThe LORD will reign for ever, Thy God, O Zion, unto all generations. Hallelujah.","note":"A morning psalm of praise for the God who lifts up the bowed down.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 146:1-10","url":"https://www.sefaria.org/Psalms.146.1-10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-148","title":"Psalm 148","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["nature","celebration"],"text":"Hallelujah. Praise ye the LORD from the heavens; Praise Him in the heights.\nPraise ye Him, all His angels; Praise ye Him, all His hosts.\nPraise ye Him, sun and moon; Praise Him, all ye stars of light.\nPraise Him, ye heavens of heavens, And ye waters that are above the heavens.\nLet them praise the name of the LORD; For He commanded, and they were created.\nHe hath also established them for ever and ever; He hath made a decree which shall not be transgressed.\nPraise the LORD from the earth, Ye sea-monsters, and all deeps;\nFire and hail, snow and vapour, Stormy wind, fulfilling His word;\nMountains and all hills, Fruitful trees and all cedars;\nBeasts and all cattle, Creeping things and winged fowl;\nKings of the earth and all peoples, Princes and all judges of the earth;\nBoth young men and maidens, Old men and children;\nLet them praise the name of the LORD, For His name alone is exalted; His glory is above the earth and heaven.\nAnd He hath lifted up a horn for His people, A praise for all His saints, Even for the children of Israel, a people near unto Him. Hallelujah.","note":"All creation called to praise: sun and moon, fire and snow, young men and maidens.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 148:1-14","url":"https://www.sefaria.org/Psalms.148.1-14?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-psalm-150","title":"Psalm 150","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","gratitude"],"text":"Hallelujah. Praise God in His sanctuary; Praise Him in the firmament of His power.\nPraise Him for His mighty acts; Praise Him according to His abundant greatness.\nPraise Him with the blast of the horn; Praise Him with the psaltery and harp.\nPraise Him with the timbrel and dance; Praise Him with stringed instruments and the pipe.\nPraise Him with the loud-sounding cymbals; Praise Him with the clanging cymbals.\nLet every thing that hath breath praise the LORD. Hallelujah.","note":"The closing psalm: let every thing that hath breath praise the LORD.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Psalms 150:1-6","url":"https://www.sefaria.org/Psalms.150.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-shema","title":"The Shema","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["daily","morning","evening","dying"],"text":"Hear, O Israel: the LORD our God, the LORD is one.\nAnd thou shalt love the LORD thy God with all thy heart, and with all thy soul, and with all thy might.\nAnd these words, which I command thee this day, shall be upon thy heart;\nand thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thy house, and when thou walkest by the way, and when thou liest down, and when thou risest up.\nAnd thou shalt bind them for a sign upon thy hand, and they shall be for frontlets between thine eyes.\nAnd thou shalt write them upon the door-posts of thy house, and upon thy gates.","translit":"Sh'ma Yisrael, Adonai Eloheinu, Adonai echad.","note":"Said morning and evening, at bedtime, and as the last words at the end of life.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Deuteronomy 6:4-9","url":"https://www.sefaria.org/Deuteronomy.6.4-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-choose-life","title":"Choose Life","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","healing"],"text":"I call heaven and earth to witness against you this day, that I have set before thee life and death, the blessing and the curse; therefore choose life, that thou mayest live, thou and thy seed;\nto love the LORD thy God, to hearken to His voice, and to cleave unto Him; for that is thy life, and the length of thy days; that thou mayest dwell in the land which the LORD swore unto thy fathers, to Abraham, to Isaac, and to Jacob, to give them.","note":"Read for a new beginning or a decision to live fully.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Deuteronomy 30:19-20","url":"https://www.sefaria.org/Deuteronomy.30.19-20?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-birkat-kohanim","title":"The Priestly Blessing","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["blessing","wedding","birth","evening"],"text":"The LORD bless thee, and keep thee;\nThe LORD make His face to shine upon thee, and be gracious unto thee;\nThe LORD lift up His countenance upon thee, and give thee peace.","translit":"Y'varech'cha Adonai v'yishm'recha.","note":"Given by parents to children on Friday night, and at weddings and partings.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Numbers 6:24-26","url":"https://www.sefaria.org/Numbers.6.24-26?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-ruth-whither","title":"Whither Thou Goest","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["wedding","funeral"],"text":"And Ruth said: 'Entreat me not to leave thee, and to return from following after thee; for whither thou goest, I will go; and where thou lodgest, I will lodge; thy people shall be my people, and thy God my God;\nwhere thou diest, will I die, and there will I be buried; the LORD do so to me, and more also, if aught but death part thee and me.'","note":"Ruth's promise to Naomi, read at weddings and at the funerals of faithful companions.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Ruth 1:16-17","url":"https://www.sefaria.org/Ruth.1.16-17?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-song-arise","title":"Arise, My Love","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["wedding","season","nature"],"text":"My beloved spoke, and said unto me: 'Rise up, my love, my fair one, and come away.\nFor, lo, the winter is past, The rain is over and gone;\nThe flowers appear on the earth; The time of singing is come, And the voice of the turtle is heard in our land;\nThe fig-tree putteth forth her green figs, And the vines in blossom give forth their fragrance. Arise, my love, my fair one, and come away.","note":"Read at weddings and at the coming of spring.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Song of Songs 2:10-13","url":"https://www.sefaria.org/Song_of_Songs.2.10-13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-song-seal","title":"Set Me as a Seal","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["wedding","funeral"],"text":"Set me as a seal upon thy heart, As a seal upon thine arm; For love is strong as death, Jealousy is cruel as the grave; The flashes thereof are flashes of fire, A very flame of the LORD.\nMany waters cannot quench love, Neither can the floods drown it; If a man would give all the substance of his house for love, He would utterly be contemned.","note":"Love is strong as death: read at weddings and at the funerals of beloved partners.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Song of Songs 8:6-7","url":"https://www.sefaria.org/Song_of_Songs.8.6-7?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-eccl-season","title":"A Time for Every Thing","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","season","grief"],"text":"To every thing there is a season, and a time to every purpose under the heaven:\nA time to be born, and a time to die; A time to plant, and a time to pluck up that which is planted;\nA time to kill, and a time to heal; A time to break down, and a time to build up;\nA time to weep, and a time to laugh; A time to mourn, and a time to dance;\nA time to cast away stones, and a time to gather stones together; A time to embrace, and a time to refrain from embracing;\nA time to seek, and a time to lose; A time to keep, and a time to cast away;\nA time to rend, and a time to sew; A time to keep silence, and a time to speak;\nA time to love, and a time to hate; A time for war, and a time for peace.","note":"Read at funerals and at turning points.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Ecclesiastes 3:1-8","url":"https://www.sefaria.org/Ecclesiastes.3.1-8?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-eccl-generation","title":"One Generation Passeth Away","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","nature"],"text":"One generation passeth away, and another generation cometh; And the earth abideth for ever.\nThe sun also ariseth, And the sun goeth down, And hasteth to his place where he ariseth.\nThe wind goeth toward the south, And turneth about unto the north; It turneth about continually in its circuit, And the wind returneth again to its circuits.\nAll the rivers run into the sea, Yet the sea is not full; Unto the place whither the rivers go, Thither they go again.","note":"The earth abideth: read for the long view of a life.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Ecclesiastes 1:4-7","url":"https://www.sefaria.org/Ecclesiastes.1.4-7?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-eccl-silver-cord","title":"Before the Silver Cord Is Snapped","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","dying"],"text":"Remember then thy Creator in the days of thy youth, and the years draw nigh, when thou shalt say: 'I have no pleasure in them';\nBefore the sun, and the light, and the moon, and the stars, are darkened, and the clouds return after the rain;\nIn the day when the keepers of the house shall tremble, and the strong men shall bow themselves, and the grinders cease because they are few, and those that look out shall be darkened in the windows,\nAnd the doors shall be shut in the street, when the sound of the grinding is low; and one shall start up at the voice of a bird, and all the daughters of music shall be brought low;\nAlso when they shall be afraid of that which is high, and terrors shall be in the way; and the almond-tree shall blossom, and the grasshopper shall drag itself along, and the caperberry shall fail; Because man goeth to his long home, and the mourners go about the streets;\nBefore the silver cord is snapped asunder, and the golden bowl is shattered, And the pitcher is broken at the fountain, and the wheel falleth shattered, into the pit;\nAnd the dust returneth to the earth as it was, and the spirit returneth unto God who gave it.","note":"An ancient poem on aging and the spirit returning to God who gave it.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Ecclesiastes 12:1-7","url":"https://www.sefaria.org/Ecclesiastes.12.1-7?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-woman-of-valour","title":"A Woman of Valour","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","celebration","home"],"text":"A woman of valour who can find? For her price is far above rubies.\nThe heart of her husband doth safely trust in her, and he hath no lack of gain.\nShe doeth him good and not evil all the days of her life.\nShe seeketh wool and flax, and worketh willingly with her hands.\nShe is like the merchant-ships; she bringeth her food from afar.\nShe riseth also while it is yet night, and giveth food to her household, and a portion to her maidens.\nShe considereth a field, and buyeth it; with the fruit of her hands she planteth a vineyard.\nShe girdeth her loins with strength, And maketh strong her arms.\nShe perceiveth that her merchandise is good; Her lamp goeth not out by night.\nShe layeth her hands to the distaff, And her hands hold the spindle.\nShe stretcheth out her hand to the poor; Yea, she reacheth forth her hands to the needy.\nShe is not afraid of the snow for her household; For all her household are clothed with scarlet.\nShe maketh for herself coverlets; Her clothing is fine linen and purple.\nHer husband is known in the gates, When he sitteth among the elders of the land.\nShe maketh linen garments and selleth them; And delivereth girdles unto the merchant.\nStrength and dignity are her clothing; And she laugheth at the time to come.\nShe openeth her mouth with wisdom; And the law of kindness is on her tongue.\nShe looketh well to the ways of her household, And eateth not the bread of idleness.\nHer children rise up, and call her blessed; Her husband also, and he praiseth her:\n'Many daughters have done valiantly, But thou excellest them all.'\nGrace is deceitful, and beauty is vain; But a woman that feareth the LORD, she shall be praised.\nGive her of the fruit of her hands; And let her works praise her in the gates.","translit":"Eshet chayil mi yimtza, v'rachok mipninim michrah.","note":"Eshet Chayil, sung on Friday night and read at the funerals of mothers and grandmothers.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Proverbs 31:10-31","url":"https://www.sefaria.org/Proverbs.31.10-31?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-tree-of-life","title":"Her Ways Are Ways of Pleasantness","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["daily","peace"],"text":"Happy is the man that findeth wisdom, And the man that obtaineth understanding.\nFor the merchandise of it is better than the merchandise of silver, And the gain thereof than fine gold.\nShe is more precious than rubies; And all the things thou canst desire are not to be compared unto her.\nLength of days is in her right hand; In her left hand are riches and honour.\nHer ways are ways of pleasantness, And all her paths are peace.\nShe is a tree of life to them that lay hold upon her, And happy is every one that holdest her fast.","translit":"Etz chayim hi lamachazikim bah.","note":"Sung as the Torah returns to the ark: she is a tree of life.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Proverbs 3:13-18","url":"https://www.sefaria.org/Proverbs.3.13-18?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-merry-heart","title":"A Merry Heart","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["healing","celebration"],"text":"A merry heart is a good medicine; But a broken spirit drieth the bones.","note":"One line on laughter as medicine.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Proverbs 17:22","url":"https://www.sefaria.org/Proverbs.17.22?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-eagles","title":"They Shall Mount Up with Wings","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["healing","hope","funeral"],"text":"Hast thou not known? hast thou not heard That the everlasting God, the LORD, The Creator of the ends of the earth, Fainteth not, neither is weary? His discernment is past searching out.\nHe giveth power to the faint; And to him that hath no might He increaseth strength.\nEven the youths shall faint and be weary, And the young men shall utterly fall;\nBut they that wait for the LORD shall renew their strength; They shall mount up with wings as eagles; They shall run, and not be weary; They shall walk, and not faint.","note":"For the weary: they that wait for the LORD shall renew their strength.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 40:28-31","url":"https://www.sefaria.org/Isaiah.40.28-31?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-by-name","title":"I Have Called Thee by Thy Name","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","birth","dying"],"text":"But now thus saith the LORD that created thee, O Jacob, And He that formed thee, O Israel: Fear not, for I have redeemed thee, I have called thee by thy name, thou art Mine.\nWhen thou passest through the waters, I will be with thee, And through the rivers, they shall not overflow thee; When thou walkest through the fire, thou shalt not be burned, Neither shall the flame kindle upon thee.","note":"For passing through deep waters.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 43:1-2","url":"https://www.sefaria.org/Isaiah.43.1-2?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-trees-clap","title":"Ye Shall Go Out with Joy","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["celebration","nature","funeral"],"text":"For ye shall go out with joy, And be led forth with peace; The mountains and the hills shall break forth before you into singing, And all the trees of the field shall clap their hands.\nInstead of the thorn shall come up the cypress, And instead of the brier shall come up the myrtle; And it shall be to the LORD for a memorial, For an everlasting sign that shall not be cut off.","note":"All the trees of the field shall clap their hands.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 55:12-13","url":"https://www.sefaria.org/Isaiah.55.12-13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-wipe-tears","title":"He Will Wipe Away Tears","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"He will swallow up death for ever; And the Lord GOD will wipe away tears from off all faces; And the reproach of His people will He take away from off all the earth; For the LORD hath spoken it.","note":"One verse of hope, read at funerals and unveilings.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 25:8","url":"https://www.sefaria.org/Isaiah.25.8?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-peaceable","title":"The Wolf Shall Dwell with the Lamb","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["peace","hope"],"text":"And the wolf shall dwell with the lamb, And the leopard shall lie down with the kid; And the calf and the young lion and the fatling together; And a little child shall lead them.\nAnd the cow and the bear feed; Their young ones shall lie down together; And the lion shall eat straw like the ox.\nAnd the sucking child shall play on the hole of the asp, And the weaned child shall put his hand on the basilisk's den.\nThey shall not hurt nor destroy In all My holy mountain; For the earth shall be full of the knowledge of the LORD, As the waters cover the sea.","note":"The vision of the peaceable kingdom.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 11:6-9","url":"https://www.sefaria.org/Isaiah.11.6-9?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-rest","title":"He Entereth into Peace","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","dying"],"text":"The righteous perisheth, And no man layeth it to heart, And godly men are taken away, None considering That the righteous is taken away from the evil to come.\nHe entereth into peace, They rest in their beds, Each one that walketh in his uprightness.","note":"Read at the funeral of a good person.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 57:1-2","url":"https://www.sefaria.org/Isaiah.57.1-2?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-mother","title":"As One Whom His Mother Comforteth","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","grief"],"text":"As one whom his mother comforteth, So will I comfort you; and ye shall be comforted in Jerusalem.","note":"One tender line of comfort.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 66:13","url":"https://www.sefaria.org/Isaiah.66.13?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-everlasting-light","title":"An Everlasting Light","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"The sun shall be no more thy light by day, Neither for brightness shall the moon give light unto thee; But the LORD shall be unto thee an everlasting light, And thy God thy glory.\nThy sun shall no more go down, Neither shall thy moon withdraw itself; For the LORD shall be thine everlasting light, And the days of thy mourning shall be ended.","note":"The days of thy mourning shall be ended.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 60:19-20","url":"https://www.sefaria.org/Isaiah.60.19-20?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-fear-not","title":"Fear Thou Not","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","healing"],"text":"Fear thou not, for I am with thee, Be not dismayed, for I am thy God; I strengthen thee, yea, I help thee; Yea, I uphold thee with My victorious right hand.","note":"One verse of courage for a hard day.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 41:10","url":"https://www.sefaria.org/Isaiah.41.10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-isaiah-mountains-depart","title":"My Kindness Shall Not Depart","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","hope"],"text":"For the mountains may depart, and the hills be removed; but My kindness shall not depart from thee, neither shall My covenant of peace be removed, saith the LORD that hath compassion on thee.","note":"For when everything else is shaking.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Isaiah 54:10","url":"https://www.sefaria.org/Isaiah.54.10?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-micah-swords","title":"Swords into Plowshares","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["peace","hope"],"text":"And He shall judge between many peoples, And shall decide concerning mighty nations afar off; And they shall beat their swords into plowshares, And their spears into pruninghooks; Nation shall not lift up sword against nation, Neither shall they learn war any more.\nBut they shall sit every man under his vine and under his fig-tree; And none shall make them afraid; For the mouth of the LORD of hosts hath spoken.","note":"Every one under his vine and fig tree: a prayer for peace.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Micah 4:3-4","url":"https://www.sefaria.org/Micah.4.3-4?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-micah-justly","title":"Do Justly, Love Mercy","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["daily","funeral"],"text":"It hath been told thee, O man, what is good, And what the LORD doth require of thee: Only to do justly, and to love mercy, and to walk humbly with thy God.","note":"One verse that sums up a good life.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Micah 6:8","url":"https://www.sefaria.org/Micah.6.8?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-lamentations-new-every-morning","title":"New Every Morning","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["grief","morning","hope"],"text":"Surely the LORD'S mercies are not consumed, Surely His compassions fail not.\nThey are new every morning; Great is Thy faithfulness.\n'The LORD is my portion', saith my soul; 'Therefore will I hope in Him.'\nThe LORD is good unto them that wait for Him, To the soul that seeketh Him.\nIt is good that a man should quietly wait For the salvation of the LORD.","note":"Hope spoken from the middle of grief.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Lamentations 3:22-26","url":"https://www.sefaria.org/Lamentations.3.22-26?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-jacob-this-place","title":"Surely the LORD Is in This Place","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["home","blessing","nature"],"text":"And Jacob awaked out of his sleep, and he said: 'Surely the LORD is in this place; and I knew it not.'\nAnd he was afraid, and said: 'How full of awe is this place! this is none other than the house of God, and this is the gate of heaven.'","note":"Jacob wakes from his dream: for blessing a place or a moment.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Genesis 28:16-17","url":"https://www.sefaria.org/Genesis.28.16-17?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-creation-light","title":"Let There Be Light","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["birth","morning","nature"],"text":"In the beginning God created the heaven and the earth.\nNow the earth was unformed and void, and darkness was upon the face of the deep; and the spirit of God hovered over the face of the waters.\nAnd God said: 'Let there be light.' And there was light.\nAnd God saw the light, that it was good; and God divided the light from the darkness.\nAnd God called the light Day, and the darkness He called Night. And there was evening and there was morning, one day.","note":"The first words of the Torah.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Genesis 1:1-5","url":"https://www.sefaria.org/Genesis.1.1-5?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-rainbow","title":"My Bow in the Cloud","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","nature","blessing"],"text":"And God said: 'This is the token of the covenant which I make between Me and you and every living creature that is with you, for perpetual generations:\nI have set My bow in the cloud, and it shall be for a token of a covenant between Me and the earth.\nAnd it shall come to pass, when I bring clouds over the earth, and the bow is seen in the cloud,\nthat I will remember My covenant, which is between Me and you and every living creature of all flesh; and the waters shall no more become a flood to destroy all flesh.\nAnd the bow shall be in the cloud; and I will look upon it, that I may remember the everlasting covenant between God and every living creature of all flesh that is upon the earth.'","note":"The rainbow covenant with every living creature.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Genesis 9:12-16","url":"https://www.sefaria.org/Genesis.9.12-16?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-love-neighbour","title":"Love Thy Neighbour","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["daily","forgiveness"],"text":"Thou shalt not take vengeance, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.","note":"The great rule of love from the Holiness Code.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Leviticus 19:18","url":"https://www.sefaria.org/Leviticus.19.18?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-strong-courage","title":"Be Strong and of Good Courage","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["comfort","healing"],"text":"Be strong and of good courage, fear not, nor be affrighted at them; for the LORD thy God, He it is that doth go with thee; He will not fail thee, nor forsake thee.'","note":"Moses to the people before the crossing.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Deuteronomy 31:6","url":"https://www.sefaria.org/Deuteronomy.31.6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-hosea-dew","title":"I Will Be as the Dew","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","nature"],"text":"I will be as the dew unto Israel; He shall blossom as the lily, And cast forth his roots as Lebanon.\nHis branches shall spread, And his beauty shall be as the olive-tree, And his fragrance as Lebanon.","note":"A promise of new growth after a hard season.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Hosea 14:6-7","url":"https://www.sefaria.org/Hosea.14.6-7?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-rachel-weeping","title":"Rachel Weeping","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["grief","comfort"],"text":"Thus saith the LORD: A voice is heard in Ramah, Lamentation, and bitter weeping, Rachel weeping for her children; She refuseth to be comforted for her children, Because they are not.\nThus saith the LORD: Refrain thy voice from weeping, And thine eyes from tears; For thy work shall be rewarded, saith the LORD; And they shall come back from the land of the enemy.","note":"For parents who have lost a child: the grief is named, and comfort is promised.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Jeremiah 31:15-16","url":"https://www.sefaria.org/Jeremiah.31.15-16?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-job-gave","title":"The LORD Gave","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["funeral","grief"],"text":"And he said; Naked came I out of my mother's womb, And naked shall I return thither; The LORD gave, and the LORD hath taken away; Blessed be the name of the LORD.","note":"Job's words, said at Jewish funerals.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Job 1:21","url":"https://www.sefaria.org/Job.1.21?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-dry-bones","title":"Can These Bones Live","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["hope","healing"],"text":"The hand of the LORD was upon me, and the LORD carried me out in a spirit, and set me down in the midst of the valley, and it was full of bones;\nand He caused me to pass by them round about, and, behold, there were very many in the open valley; and, lo, they were very dry.\nAnd He said unto me: 'Son of man, can these bones live?' And I answered: 'O Lord GOD, Thou knowest.'\nThen He said unto me: 'Prophesy over these bones, and say unto them: O ye dry bones, hear the word of the LORD:\nThus saith the Lord GOD unto these bones: Behold, I will cause breath to enter into you, and ye shall live.\nAnd I will lay sinews upon you, and will bring up flesh upon you, and cover you with skin, and put breath in you, and ye shall live; and ye shall know that I am the LORD.'","note":"The vision of breath returning, read for hope beyond despair.","voice":"brian","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), Ezekiel 37:1-6","url":"https://www.sefaria.org/Ezekiel.37.1-6?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-all-things-come","title":"All Things Come of Thee","by":"Hebrew Bible","tr":"Jewish Publication Society","year":1917,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"scripture","occasion":["gratitude","funeral"],"text":"Thine, O LORD, is the greatness, and the power, and the glory, and the victory, and the majesty; for all that is in the heaven and in the earth is Thine; Thine is the kingdom, O LORD, and Thou art exalted as head above all.\nBoth riches and honour come of Thee, and Thou rulest over all; and in Thy hand is power and might; and in Thy hand it is to make great, and to give strength unto all.\nNow therefore, our God, we thank Thee, and praise Thy glorious name.\nBut who am I, and what is my people, that we should be able to offer so willingly after this sort? for all things come of Thee, and of Thine own have we given Thee.\nFor we are strangers before Thee, and sojourners, as all our fathers were: our days on the earth are as a shadow, and there is no abiding.","note":"David's blessing: of Thine own have we given Thee; our days are as a shadow.","voice":"jenny","source":{"name":"The Holy Scriptures According to the Masoretic Text, JPS (1917), I Chronicles 29:11-15","url":"https://www.sefaria.org/I_Chronicles.29.11-15?lang=en&ven=The_Holy_Scriptures_A_New_Translation_JPS_1917"},"rights":"pd","pd":"published 1917 by the Jewish Publication Society of America; public domain in the United States"},{"id":"abr-avot-three-things","title":"Upon Three Things the World Rests","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","funeral"],"text":"Simon, the Just, was of the last survivors of the Great Synagogue. He used to say, \"Upon three things the world rests: upon the Torah, upon the Temple service, and upon the doing of acts of kindness.\"","note":"Studied on Sabbath afternoons; a fine summary of a life of kindness.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-hillel","title":"If I Am Not for Myself","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","hope"],"text":"Hillel said, \"Be of the disciples of Aaron, loving peace and pursuing peace, loving mankind and drawing them nigh to the Torah.\"\nHe used to say, \"If I am not for myself, who will be for me? But if I care for myself only, what am I? And if not now, when?\"","translit":"Im ein ani li, mi li? U'chshe'ani l'atzmi, mah ani? V'im lo achshav, eimatai?","note":"Hillel's sayings, loved for teaching peace and the call to act now.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-shammai","title":"Say Little and Do Much","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","home"],"text":"Shammai said, \"Set a fixed time for thy (study of) Torah; say little and do much; and receive all men with a cheerful countenance.\"","note":"Shammai's counsel on welcome and on doing.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-truth-peace","title":"Truth, Judgment, and Peace","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["peace","daily"],"text":"Rabban Simeon, the son of Gamaliel said, \"By three things is the world preserved; by truth, by judgment, and by peace, as it is said, 'Judge ye the truth and the judgment of peace in your gates.'\"","note":"The world preserved by truth, justice, and peace.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-judge-not","title":"Judge Not Thy Neighbor","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","forgiveness"],"text":"Hillel said, \"Separate not thyself from the congregation; trust not in thyself until the day of thy death; judge not thy neighbor until thou art come into his place; and say not anything which cannot be understood at once, in the hope that it will be understood in the end; neither say, 'When I have leisure I will study'; perchance thou wilt have no leisure.\"","note":"Hillel on community and on judging others kindly.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-good-way","title":"Go Forth and See Which Is the Good Way","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","funeral"],"text":"He said to them, \"Go forth and see which is the good way to which a man should cleave.\" R. Eliezer said, \"A good eye\"; R. Joshua said, \"A good friend\"; R. Jose said, \"A good neighbor\"; R. Simeon said, \"One who foresees the fruit of an action\"; R. Eleazar said, \"A good heart.\" Thereupon he said to them, \"I approve of the words of Eleazar, the son of Arach, rather than your words, for in his words yours are included.\"","note":"A teacher asks his students for the best way to live; the answer is a good heart.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-day-is-short","title":"The Day Is Short","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","funeral","hope"],"text":"Rabbi Tarfon said, \"The day is short, the task is great, the laborers are sluggish, the reward is much, and the Master of the house is urgent.\" He also used to say, \"It is not thy duty to complete the work, but neither art thou free to desist from it.\"","note":"Rabbi Tarfon's words for unfinished work: we are not asked to complete it, only to keep at it.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-ben-zoma","title":"Who Is Wise","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","gratitude"],"text":"Ben Zoma said, \"Who is wise? He who learns from all men, as it is said, 'from all my teachers have I gotten understanding.' Who is mighty? He who controls his passions, as it is said, 'He that is slow to anger is better than the mighty, and he that ruleth over his spirit than he that taketh a city.' Who is rich? He who rejoices in his portion, as it is said, 'When thou eatest the labor of thine hands, happy art thou, and it shall be well with thee'; happy art thou in this world, and it shall be well with thee in the world to come. Who is honored? He who honors others, as it is said, 'For them that honor me I will honor, and they that despise me shall be held in contempt.'\"","note":"Who is rich? He who rejoices in his portion.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-every-man-his-hour","title":"Every Man Has His Hour","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","comfort"],"text":"He used to say, \"Despise not any man, and carp not at any thing; for there is not a man that has not his hour, and there is not a thing that has not its place.\"","note":"Ben Azzai: every person has an hour and every thing a place.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-crown-good-name","title":"The Crown of a Good Name","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["funeral","celebration"],"text":"R. Simeon said, \"There are three crowns: the crown of Torah, the crown of priesthood, and the crown of royalty; but the crown of a good name excels them all.\"","note":"Read in eulogies: the crown of a good name excels them all.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-greet-peace","title":"Be First to Greet","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["peace","daily"],"text":"R. Mattithiah, the son of Heresh, said, \"Be beforehand in the salutation of peace to all men; and be rather a tail to lions than a head to foxes.\"","note":"Be first to offer a greeting of peace to every person.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-vestibule","title":"This World Is Like a Vestibule","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["funeral","dying","hope"],"text":"R. Jacob said, \"This world is like a vestibule before the world to come; prepare thyself in the vestibule, that thou mayest enter into the hall.\" He used to say, \"Better is one hour of repentance and good deeds in this world than the whole life of the world to come; and better is one hour of blissfulness of spirit in the world to come than the whole life of this world.\"","note":"Read at funerals for its picture of this life and the life to come.","voice":"jenny","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-avot-comforting-mourner","title":"On Comforting a Mourner","by":"Pirkei Avot (Mishnah)","tr":"Joseph I. Gorfinkle","year":1913,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["grief","funeral"],"text":"R. Simeon, the son of Eleazer, said, \"Do not appease thy fellow in the hour of his anger, and comfort him not in the hour when his dead lies before him, and question him not in the hour of his vow, and rush not to see him in the hour of his disgrace.\"","note":"Ancient guidance for visitors: in the first hour, presence matters more than words.","voice":"brian","source":{"name":"The Sayings of the Jewish Fathers, tr. Gorfinkle (1913), Project Gutenberg #8548","url":"https://www.gutenberg.org/ebooks/8548"},"rights":"pd","pd":"published 1913 (Bloch, New York); public domain in the United States"},{"id":"abr-keter-thou-art-one","title":"Thou Art One, from The Royal Crown","by":"Solomon ibn Gabirol","tr":"Israel Zangwill","year":1923,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"poem","occasion":["daily","evening"],"text":"Thou art One, the first of every number, and the foundation of every structure,\nThou art One, and at the mystery of Thy Oneness the wise of heart are struck dumb, For they know not what it is.\nThou art One, and Thy Oneness can neither be increased nor lessened, It lacketh naught, nor doth aught remain over.\nThou art One, but not like a unit to be grasped or counted, For number and change cannot reach Thee. Thou art not to be visioned, nor to be figured thus or thus.\nThou art One, but to put to Thee bound or circumference my imagination would fail me. Therefore I have said I will guard my ways lest I sin with the tongue.\nThou art One, Thou art high and exalted beyond abasement or falling, \"For how should the One fall?\"","note":"From the long poem many read on the eve of Yom Kippur.","voice":"jenny","source":{"name":"Selected Religious Poems of Solomon Ibn Gabirol, tr. Zangwill (JPS, 1923), The Royal Crown","url":"https://www.sefaria.org/Keter_Malkhut?lang=en&ven=Selected_Religious_Poems_of_Solomon_Ibn_Gabirol,_trans._Israel_Zangwill._JPS,_Philadelphia,_1923"},"rights":"pd","pd":"published 1923 by the Jewish Publication Society; public domain in the United States"},{"id":"abr-keter-thou-existest","title":"Thou Existest, from The Royal Crown","by":"Solomon ibn Gabirol","tr":"Israel Zangwill","year":1923,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"poem","occasion":["daily","peace"],"text":"Thou existest, but hearing of ear cannot reach Thee, or vision of eye, Nor shall the How have sway over Thee, nor the Wherefore and Whence.\nThou existest, but for Thyself and for none other with Thee.\nThou existest, and before Time began Thou wast, And without place Thou didst abide.\nThou existest, and Thy secret is hidden and who shall attain to it? So deep, so deep, who can discover it?","note":"A meditation on the hidden, eternal One.","voice":"brian","source":{"name":"Selected Religious Poems of Solomon Ibn Gabirol, tr. Zangwill (JPS, 1923), The Royal Crown","url":"https://www.sefaria.org/Keter_Malkhut?lang=en&ven=Selected_Religious_Poems_of_Solomon_Ibn_Gabirol,_trans._Israel_Zangwill._JPS,_Philadelphia,_1923"},"rights":"pd","pd":"published 1923 by the Jewish Publication Society; public domain in the United States"},{"id":"abr-keter-thou-livest","title":"Thou Livest, from The Royal Crown","by":"Solomon ibn Gabirol","tr":"Israel Zangwill","year":1923,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"poem","occasion":["dying","hope"],"text":"Thou livest, but not from any restricted season nor from any known period.\nThou livest, but not through breath and soul, for Thou art soul of the soul.\nThou livest, but not with the life of man, which is like unto vanity and its end the moth and the worm.\nThou livest, and he who layeth hold of Thy secret shall find eternal delight: \"He shall eat and live for ever.\"","note":"Thou art soul of the soul.","voice":"jenny","source":{"name":"Selected Religious Poems of Solomon Ibn Gabirol, tr. Zangwill (JPS, 1923), The Royal Crown","url":"https://www.sefaria.org/Keter_Malkhut?lang=en&ven=Selected_Religious_Poems_of_Solomon_Ibn_Gabirol,_trans._Israel_Zangwill._JPS,_Philadelphia,_1923"},"rights":"pd","pd":"published 1923 by the Jewish Publication Society; public domain in the United States"},{"id":"abr-keter-light","title":"Thou Art Light, from The Royal Crown","by":"Solomon ibn Gabirol","tr":"Israel Zangwill","year":1923,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"poem","occasion":["funeral","hope"],"text":"Thou art Light celestial, and the eyes of the pure shall behold Thee But the clouds of sin shall veil Thee from the eyes of the sinners.\nThou art Light, hidden in this world but to be revealed in the visible world on high. \"On the mount of the Lord shall it be seen.\"\nLight Eternal art Thou, and the eye of the intellect longeth and yearneth for Thee. \"Yet only a part shall it see, the whole it shall not behold.\"","note":"Light hidden in this world, longed for by the eye of the heart.","voice":"brian","source":{"name":"Selected Religious Poems of Solomon Ibn Gabirol, tr. Zangwill (JPS, 1923), The Royal Crown","url":"https://www.sefaria.org/Keter_Malkhut?lang=en&ven=Selected_Religious_Poems_of_Solomon_Ibn_Gabirol,_trans._Israel_Zangwill._JPS,_Philadelphia,_1923"},"rights":"pd","pd":"published 1923 by the Jewish Publication Society; public domain in the United States"},{"id":"abr-baalshem-neighbour","title":"All Serve God, a Saying of the Baal Shem Tov","by":"Israel Baal Shem Tov, as told by Solomon Schechter","year":1896,"trad":["jewish"],"denom":["orthodox","hasidic"],"type":"reflection","occasion":["daily","forgiveness"],"text":"Baalshem said, \"Let no one think himself better than his neighbour, for all serve God; each according to the measure of understanding which God has given him.\"","note":"A Hasidic teaching on humility and seeing the good in every person.","voice":"jenny","source":{"name":"Solomon Schechter, Studies in Judaism (1896), \"The Chassidim,\" Project Gutenberg #48890","url":"https://www.gutenberg.org/ebooks/48890"},"rights":"pd","pd":"published 1896; Schechter died 1915"},{"id":"abr-baalshem-king","title":"To Be with the King, a Teaching of the Baal Shem Tov","by":"Israel Baal Shem Tov, as told by Solomon Schechter","year":1896,"trad":["jewish"],"denom":["orthodox","hasidic"],"type":"reflection","occasion":["daily","peace"],"text":"The wise man, says Baalshem, does not trouble the king with innumerable petitions about trifles. His desire is merely to gain admission into the king's presence and to speak with him without a go-between. To be with the king whom he loves so dearly is for him the highest good. But his love for the king has its reward; for the king loves him.","note":"The Baal Shem Tov on prayer as simply drawing near.","voice":"brian","source":{"name":"Solomon Schechter, Studies in Judaism (1896), \"The Chassidim,\" Project Gutenberg #48890","url":"https://www.gutenberg.org/ebooks/48890"},"rights":"pd","pd":"published 1896; Schechter died 1915"},{"id":"abr-talmud-sayings","title":"Sayings from the Talmud","by":"Talmud and Jewish tradition","year":1901,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"reflection","occasion":["daily","home","gratitude"],"text":"Do not to others what you would not have others do to you.\nA single light answers as well for a hundred men as for one.\nUse thy best vase to-day, for to-morrow it may, perchance, be broken.\nOur kindly deeds and our generous gifts go to heaven as messengers, and plead for us before our Heavenly Father.\nThe world is a wedding.\nA myrtle even in the desert remains a myrtle.\nTeach thy tongue to say, \"I do not know.\"\nHospitality is an expression of Divine worship.\nThe place honors not the man, 'tis the man who gives honor to the place.\nThe rose grows among thorns.\nThe consciousness of God's presence is the first principle of religion.","note":"Short sayings for a table talk, a eulogy, or a wall at home.","voice":"jenny","source":{"name":"Hebraic Literature: Translations from the Talmud, Midrashim and Kabbala (1901), Project Gutenberg #14368","url":"https://www.gutenberg.org/ebooks/14368"},"rights":"pd","pd":"published 1901 (M. Walter Dunne, New York); public domain in the United States"},{"id":"abr-kaddish","title":"The Mourner's Kaddish","by":"Jewish liturgy","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"prayer","occasion":["funeral","grief","daily"],"text":"Magnified and sanctified be his great name in the world which he hath created according to his will. May he establish his kingdom during your life and during your days, and during the life of all the house of Israel, even speedily and at a near time, and say ye, Amen.\n\nLet his great name be blessed for ever and to all eternity.\n\nBlessed, praised and glorified, exalted, extolled and honored, magnified and lauded be the name of the Holy One, blessed be he; though he be high above all the blessings and hymns, praises and consolations, which are uttered in the world; and say ye, Amen.\n\nMay there be abundant peace from heaven, and life for us and for all Israel; and say ye, Amen.\n\nHe who maketh peace in his high places, may he make peace for us and for all Israel; and say ye, Amen.","translit":"Yitgadal v'yitkadash sh'mei raba, b'alma di v'ra chirutei.","note":"Said by mourners with a minyan for eleven months, and every year on the yahrzeit.","voice":"brian","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb06.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-elohai-neshama","title":"The Soul Which Thou Gavest Me Is Pure","by":"Jewish liturgy","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"prayer","occasion":["morning","daily","dying"],"text":"O my God, the soul which thou gavest me is pure; thou didst create it, thou didst form it, thou didst breathe it into me; thou preservest it within me; and thou wilt take it from me, but wilt restore it unto me hereafter.\n\nSo long as the soul is within me, I will give thanks unto thee, O Lord my God and God of my fathers, Sovereign of all works, Lord of all souls!","translit":"Elohai, neshamah shenatata bi tehorah hi.","note":"Said each morning on waking; also a gentle prayer at the end of life.","voice":"jenny","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb05.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-adon-olam","title":"Adon Olam","by":"Jewish liturgy, attributed to Solomon ibn Gabirol","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"hymn","occasion":["evening","dying","comfort","daily"],"text":"He is Lord of the universe, who reigned ere any creature yet was formed: At the time when all things were made by his desire, then was his name proclaimed King.\n\nAnd after all things shall have had an end, he alone, the dreaded one, shall reign; Who was, who is, and who will be in glory.\n\nAnd he is One, and there is no second to compare to him, to consort with him: Without beginning, without end: to him belong strength and dominion.\n\nAnd he is my God, my Redeemer liveth, and a rock in my travail in time of distress; And he is my banner and my refuge, the portion of my cup on the day when I call.\n\nInto his hand I commend my spirit, when I sleep and when I wake: And with my spirit, my body also: the Lord is with me, and I will not fear.","translit":"Adon olam asher malach, b'terem kol y'tzir nivra.","note":"A hymn sung at the close of services, at bedtime, and at the bedside of the dying.","voice":"brian","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb05.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-shehecheyanu","title":"Who Hast Kept Us in Life","by":"Jewish liturgy","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["celebration","birth","season","gratitude"],"text":"Blessed art thou, O Lord our God, King of the universe, who hast kept us in life, and hast preserved us, and enabled us to reach this season.","translit":"Baruch atah Adonai, Eloheinu melech ha'olam, shehecheyanu v'kiy'manu v'higiyanu lazman hazeh.","note":"Said at a first time, a new season, a birth, or a long awaited day.","voice":"jenny","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb25.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-dayan-emet","title":"Blessed Be the True Judge","by":"Jewish liturgy","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["funeral","grief","dying"],"text":"Blessed art thou, O Lord our God, King of the universe, the true Judge.","translit":"Baruch atah Adonai, Eloheinu melech ha'olam, dayan ha'emet.","note":"Said on hearing of a death and at the tearing of a garment before the funeral.","voice":"brian","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb44.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-rainbow-blessing","title":"On Seeing a Rainbow","by":"Jewish liturgy","tr":"Simeon Singer","year":1890,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["nature","hope","blessing"],"text":"Blessed art thou, O Lord our God, King of the universe, who rememberest the covenant, art faithful to thy covenant, and keepest thy promise.","translit":"Baruch atah Adonai, Eloheinu melech ha'olam, zocher habrit.","note":"A short blessing said on seeing a rainbow.","voice":"brian","source":{"name":"The Authorised Daily Prayer Book, tr. Simeon Singer (1890; 1915 printing), sacred-texts.com","url":"https://sacred-texts.com/jud/spb/spb44.htm"},"rights":"pd","pd":"first published 1890; Singer died 1906"},{"id":"abr-gb-shiva-house","title":"A Word for the House of Mourning","by":"Grow With Grounded","year":2026,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["grief","funeral","home"],"text":"We came to sit with you.\nWe brought our quiet, and our love.\nYour grief has room here.\nYour stories have room here.\nMay the One who comforts all mourners comfort you,\nand may your loved one's memory be a blessing.","note":"A Grounded word for visitors to a shiva house; it honors the tradition of quiet presence.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded"},{"id":"abr-gb-unveiling","title":"For the Unveiling of a Stone","by":"Grow With Grounded","year":2026,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["grief","funeral","season"],"text":"A year of seasons has passed.\nWe stand together at this stone,\nwhich keeps a name, a story, and a place to return to.\nWe leave a small stone of our own:\nwe were here, we remember, we carry you with us.\nMay your memory be a blessing.","note":"A Grounded word for the unveiling, often held near the end of the first year.","voice":"brian","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded"},{"id":"abr-gb-yahrzeit","title":"For Lighting a Yahrzeit Candle","by":"Grow With Grounded","year":2026,"trad":["jewish"],"denom":["reform","conservative","orthodox","reconstructionist"],"type":"blessing","occasion":["grief","evening","season"],"text":"This small flame burns through the night and into tomorrow.\nIt holds the light of a life we love.\nWe remember your voice, your hands, your ways.\nWe give thanks for every year we had.\nMay your memory be a blessing,\nand may your light keep teaching us how to live.","note":"A Grounded word to say as the memorial candle is lit on the anniversary of a death.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded"},{"id":"abr-quran-fatiha","title":"The Opening (Al-Fatiha)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","funeral","dying","blessing"],"text":"In the name of Allah, the Beneficent, the Merciful.\nPraise be to Allah, Lord of the Worlds,\nThe Beneficent, the Merciful.\nMaster of the Day of Judgment,\nThee (alone) we worship; Thee (alone) we ask for help.\nShow us the straight path,\nThe path of those whom Thou hast favoured; Not the (path) of those who earn Thine anger nor of those who go astray.","translit":"Bismillahir rahmanir rahim. Al hamdu lillahi rabbil alamin.","note":"The opening surah, said in every prayer, at the bedside, and for the one who has died.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 1:1-7, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-ayat-kursi","title":"The Throne Verse (Ayat al-Kursi)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","evening","dying","home"],"text":"Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous.","translit":"Allahu la ilaha illa huwal hayyul qayyum.","note":"Recited for protection at night, in the home, and beside the sick and dying.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:255, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-inna-lillahi","title":"Surely unto Him We Are Returning","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["grief","funeral","dying","comfort"],"text":"And surely We shall try you with something of fear and hunger, and loss of wealth and lives and crops; but give glad tidings to the steadfast,\nWho say, when a misfortune striketh them: Lo! we are Allah's and lo! unto Him we are returning.\nSuch are they on whom are blessings from their Lord, and mercy. Such are the rightly guided.","translit":"Inna lillahi wa inna ilayhi raji'un.","note":"The verses behind the words said on hearing of a death: Inna lillahi wa inna ilayhi raji'un.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:155-157, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-remember-me","title":"Remember Me, I Will Remember You","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","comfort"],"text":"Therefore remember Me, I will remember you. Give thanks to Me, and reject not Me.\nO ye who believe! Seek help in steadfastness and prayer. Lo! Allah is with the steadfast.","note":"A call to remembrance, thanks, patience, and prayer.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:152-153, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-i-am-near","title":"I Am Near","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","daily"],"text":"And when My servants question thee concerning Me, then surely I am nigh. I answer the prayer of the suppliant when he crieth unto Me. So let them hear My call and let them trust in Me, in order that they may be led aright.","note":"A verse of nearness, loved in Ramadan and in hard nights.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:186, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-no-burden","title":"No Soul Is Burdened Beyond Its Scope","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","healing","evening"],"text":"Allah tasketh not a soul beyond its scope. For it (is only) that which it hath earned, and against it (only) that which it hath deserved. Our Lord! Condemn us not if we forget, or miss the mark! Our Lord! Lay not on us such a burden as thou didst lay on those before us! Our Lord! Impose not on us that which we have not the strength to bear! Pardon us, absolve us and have mercy on us, Thou, our Protector, and give us victory over the disbelieving folk.","note":"The closing verse of the long second surah, often recited at night.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:286, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-righteousness","title":"What Righteousness Is","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily"],"text":"It is not righteousness that ye turn your faces to the East and the West; but righteous is he who believeth in Allah and the Last Day and the angels and the Scripture and the prophets; and giveth wealth, for love of Him, to kinsfolk and to orphans and the needy and the wayfarer and to those who ask, and to set slaves free; and observeth proper worship and payeth the poor-due. And those who keep their treaty when they make one, and the patient in tribulation and adversity and time of stress. Such are they who are sincere. Such are the Allah-fearing.","note":"A verse on true goodness: belief joined to care for kin, orphans, the needy, and the traveler.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:177, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-give-us-good","title":"Give Us Good in This World","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","blessing","wedding"],"text":"And of them (also) is he who saith: \"Our Lord! Give unto us in the world that which is good and in the Hereafter that which is good, and guard us from the doom of Fire.\"","translit":"Rabbana atina fid dunya hasanah, wa fil akhirati hasanah.","note":"A short prayer said often, including at weddings and journeys.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:201, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-wherever-you-turn","title":"Wherever You Turn","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["nature","peace","comfort"],"text":"Unto Allah belong the East and the West, and whithersoever ye turn, there is Allah's Countenance. Lo! Allah is All-Embracing, All-Knowing.","note":"Unto Allah belong the East and the West: for prayer far from home.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:115, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-signs-creation","title":"Signs for Those of Understanding","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["nature","evening","gratitude"],"text":"Lo! In the creation of the heavens and the earth and (in) the difference of night and day are tokens (of His Sovereignty) for men of understanding,\nSuch as remember Allah, standing, sitting, and reclining, and consider the creation of the heavens and the earth, (and say): Our Lord! Thou createdst not this in vain. Glory be to Thee! Preserve us from the doom of Fire.","note":"Verses for looking at the sky, said by the Prophet on rising at night.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 3:190-191, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-every-soul","title":"Every Soul Will Taste of Death","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","dying"],"text":"Every soul will taste of death. And ye will be paid on the Day of Resurrection only that which ye have fairly earned. Whoso is removed from the Fire and is made to enter paradise, he indeed is triumphant. The life of this world is but comfort of illusion.","note":"A plain verse on mortality, read at funerals.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 3:185, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-hearts-rest","title":"In the Remembrance of Allah Hearts Find Rest","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","peace","daily"],"text":"Who have believed and whose hearts have rest in the remembrance of Allah. Verily in the remembrance of Allah do hearts find rest!","note":"One verse of rest for an anxious heart.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 13:28, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"}];
